// =============================================================================
//   Swaps found through a wallet
// =============================================================================

/** The ticket's wallet list message, as it stands now. */
const walletList = (world) => world.channel.history.find((m) => readWalletEmbed(m.embeds[0]?.data ?? m.embeds[0]))

/** The ticket's details-embed messages, in posting order. */
const detailsMessages = (world) => world.channel.history.filter((m) => (m.embeds[0]?.data ?? m.embeds[0])?.title?.startsWith('Meson swap'))

test('a wallet\'s unfinished swaps are each posted in reply to its list and followed, and the list is kept current', async () => {
  const wallet = '0x' + 'e1'.repeat(20)
  const a = swapId('5')
  const b = swapId('6')
  const events = { [a]: MOVING, [b]: MOVING }
  stubMeson({ events, overdue: [b], walletSwaps: [swapRecord(a, MOVING), swapRecord(b, MOVING)] })
  const world = makeWorld('w11')
  onTicketMessage(world.message(110, world.user, { content: `my wallet ${wallet}` }))
  await sleep(400)

  const list = walletList(world)
  assert.equal(list.embeds[0].data.title, 'Unfinished Meson swaps for this wallet: 2')
  assert.deepEqual(list.embeds[0].data.fields.map((f) => f.name), ['1) ⚪ Bonded', '2) 🔴 Expired*', 'Checked'])
  assert.equal(list.embeds[0].data.fields[0].value, `[${a}](https://explorer.meson.fi/swap/${a})`, 'only the linked swap ID')
  const details = detailsMessages(world)
  assert.deepEqual(details.map((m) => m.reference?.messageId), [list.id, list.id], 'each a reply to the list')
  assert.deepEqual(details.map((m) => m.embeds[0].data.title), ['Meson swap #1 — Bonded', 'Meson swap #2 — Expired*'])
  assert.ok(world.channel.history.some((m) => m.content.startsWith('⏳ **Swap #1**')), 'renumbered once #2 arrived')
  assert.ok(world.channel.history.some((m) => m.content.startsWith('🔎 **Swap #2**')))

  events[a] = DONE
  await sleep(2500)
  assert.equal(closings(world.posted).length, 1)
  assert.ok(closings(world.posted)[0].includes('Swap #1') && !closings(world.posted)[0].includes(CLOSING_SOON), 'not "closed soon" while Swap #2 is open')
  assert.equal(walletList(world).embeds[0].data.title, 'Unfinished Meson swaps for this wallet: 1 of 2')
  assert.deepEqual(walletList(world).embeds[0].data.fields.map((f) => f.name), ['1) 🟢 Done', '2) 🔴 Expired*', 'Checked'])

  events[b] = DONE
  await sleep(2500)
  assert.equal(closings(world.posted).length, 2)
  assert.ok(closings(world.posted)[1].includes('Swap #2') && closings(world.posted)[1].includes(CLOSING_SOON), 'the last one closes the ticket')
  assert.equal(walletList(world).embeds[0].data.title, 'All Meson swaps for this wallet are now finished')
})

test('after a restart a wallet list is still kept current, and a listed swap never posted is posted then', async () => {
  const wallet = '0x' + 'e2'.repeat(20)
  const a = swapId('7')
  const b = swapId('8')
  const events = { [a]: MOVING, [b]: MOVING }
  stubMeson({ events, walletSwaps: [swapRecord(a, MOVING), swapRecord(b, MOVING)] })
  const world = makeWorld('w12')
  const restart = restartable(world)
  const first = world.message(120, world.user, { content: wallet })
  world.channel.history = [first]
  onTicketMessage(first)
  await sleep(400)
  assert.equal(detailsMessages(world).length, 2)

  // The bot stopped before Swap #2 was posted: take its details embed and replies out of the history.
  stopWatchingChannel('w12')
  const second = detailsMessages(world)[1]
  world.channel.history = world.channel.history.filter((m) => m !== second && m.reference?.messageId !== second.id)
  await restart()
  const list = walletList(world)
  const details = detailsMessages(world)
  assert.equal(details.length, 2, 'Swap #2 is posted, Swap #1 not again')
  assert.equal(details[1].reference.messageId, list.id)
  assert.equal(details[1].embeds[0].data.title, 'Meson swap #2 — Bonded')

  events[a] = DONE
  await sleep(2500)
  assert.deepEqual(walletList(world).embeds[0].data.fields.map((f) => f.name), ['1) 🟢 Done', '2) ⚪ Bonded', 'Checked'])
  assert.equal(walletList(world).embeds[0].data.title, 'Unfinished Meson swaps for this wallet: 1 of 2')
})

test('a wallet list whose first swap fails to post is finished on the retry, without a ❓ for the value it named', async () => {
  const wallet = '0x' + 'e3'.repeat(20)
  const unknown = `0x${'e4'.repeat(32)}`
  const a = swapId('9')
  stubMeson({ events: { [a]: MOVING }, walletSwaps: [swapRecord(a, MOVING)] })
  const world = makeWorld('w13')
  const m = world.message(130, world.user, { content: `${unknown} ${wallet}` })
  // The list posts; its first reply (Swap #1's details) fails once, as on a Discord hiccup.
  const reply = m.reply
  m.reply = async (payload) => {
    const list = await reply(payload)
    const listReply = list.reply
    let failures = 1
    list.reply = async (p) => { if (failures-- > 0) throw new Error('Discord 500'); return listReply(p) }
    return list
  }
  onTicketMessage(m)
  await sleep(2000) // the retry (TICKET_RETRY_SECONDS)
  assert.equal(detailsMessages(world).length, 1, 'Swap #1 posted on the retry')
  assert.equal(world.posted.filter((p) => p.embeds?.[0]?.data?.url?.includes('/address/')).length, 1, 'one list')
  assert.ok(!texts(world.posted).some((x) => x.startsWith('❓')), 'the list already named the value')
})

test('a re-listed wallet embed sends back only what the bot set, not the read-only keys Discord adds', async () => {
  const id = swapId('3')
  stubMeson({ events: { [id]: DONE } })
  const swap = (await getSwaps([id])).get(id)
  const fetched = { type: 'rich', content_scan_version: 1, title: 'Unfinished Meson swaps for this wallet: 1', url: 'https://explorer.meson.fi/address/0xab', description: '`0xab`', color: 1, footer: { text: 'auto-detected from this ticket', proxy_icon_url: 'x' }, fields: [{ name: '1) ⚪ Bonded', value: `[${id}](x)`, inline: false }, { name: 'Checked', value: 'all 1 swap(s)' }] }
  const [embed] = relistWalletEmbeds([fetched], [swap])
  const data = JSON.parse(JSON.stringify(embed.toJSON())) // as sent to Discord
  assert.deepEqual(Object.keys(data).sort(), ['color', 'description', 'fields', 'footer', 'title', 'url'])
  assert.deepEqual(data.footer, { text: 'auto-detected from this ticket' })
  assert.equal(data.title, 'All Meson swaps for this wallet are now finished')
  assert.deepEqual(data.fields.map((f) => f.name), ['1) 🟢 Done', 'Checked'])
})
